; raycast.asm - generated by gen_raycast.py, do not edit
;
; Placard CPU (a ROM program that uses the standard library)
;
;     python3 gen_raycast.py                  writes raycast.asm next to this script
;     python3 gen_raycast.py --preview p.png  also draws the first view with the
;                                             Python model (no CPU)
;     python3 test_raycast_sim.py             runs it in placard_sim and checks
;                                             every view against the model
;
; SCREEN
;     rows   0-31   1 bpp, 1x   four lines of 80 column text: title, frame
;                               rate, controls, demo / player mode
;     rows  32-479  8 bpp, 4x   the 3D view: 80 x 112 cells of 8 x 4 pixels,
;                               256 colors (RGB 3-3-2)
;     The 1x text rows use video offsets x020-x03F of each byte column and the
;     4x view rows x180-x1FF (docs/VIDEO.md, line repeat), so they never share a
;     byte.  There is no page flip, so a view is drawn over the last one,
;     column by column, while it is on the screen.
;
; WHY IT IS FAST ON THIS MACHINE
;     Video memory is column-major: the 112 cells of one view column are 112
;     bytes of one 512-byte page pair (Y = x61 + 2 * column, X = the row's
;     offset), so a wall slice is a run of stores with the X offsets as
;     immediates.  The program has three unrolled store runs in ROM, one for
;     the ceiling, one for the floor and one for the wall, and enters each at
;     the right place for the wall height h (0-56 cells above and below the
;     middle).  Every cell costs 6 clocks (ld n, x / ld c, [y,x]), so a whole
;     column is 672 clocks, whatever the wall height.  The ceiling and floor
;     colors are immediates in the code (fixed gradients); the wall color is
;     in AC.
;
; THE RAY CASTER (one ray per column, DDA on a 16 x 16 map)
;     Player position 8.8 fixed point (high byte = map cell), angle 0-255
;     (1.4 degrees a step).  Ray angles are 0-1023: ray c has angle
;     4 * angle + COLANG[c], COLANG = atan(0.66 * camera x) (66 degree field
;     of view).  For each ray:
;       - DDX, DDY = |1 / cos|, |1 / sin| of the ray angle, 8.8, from 1 KB
;         tables (clamped to x3FFF); the steps (+-1 cell) from the quadrant
;       - the first crossing distances side = f * dd / 256, f = the distance
;         to the next cell edge in 1/256 cell (255 - frac or frac), with two
;         8 x 8 quarter-square multiplies (a * b = Q(a + b) - Q(|a - b|),
;         Q(n) = n * n / 4, 2 KB of tables)
;       - DDA: step along x when sideX < sideY, else along y, adding dd with
;         the carry flag, until the map cell is a wall
;       - distance = side - dd of the axis that hit (the distance along the
;         ray), half height hr = 60.6 / distance from a 6 KB table
;         (distance high byte 0-23 picks the page, low byte the entry), then
;         the fish-eye correction h = hr + hr * KC[c] / 256 (KC = 1 / cos of
;         the column's angle offset, minus 1), at most 56
;       - wall color COLTAB[type * 32 + side * 16 + parity * 8 + h / 8]: a
;         color for each wall type, darker for y sides, every other map cell
;         a little darker (so blocks show), and darker with distance
;     About 2,000 clocks a column with the drawing, so a whole view takes
;     about 1.7 frames: around 30 views a second (the HUD shows the rate).
;
; CONTROLS
;     Arrow keys or SNES pad 1: Up / Down walk, Left / Right turn.  With no
;     input for 10 s the demo walk (a fixed script) takes over again; it
;     starts in the demo walk.  Movement is per frame (tick), so the speed
;     doesn't depend on the view rate: 1/18 cell a tick, turning 2 steps
;     (2.8 degrees) a tick.  Walls are kept 1/4 cell away; each axis is
;     tried on its own, so the player slides along walls.
;
; Date: 10/19/2026

#include "placard.asm"
#include "placard_lib.asm"

; ---------------------------------------------------------------------------
; program variables (zero page x20-x8F)
; ---------------------------------------------------------------------------
pa         = 0x20       ; player angle 0-255
pxl        = 0x21       ; player x, 8.8 (pxh = map column)
pxh        = 0x22
pyl        = 0x23       ; player y, 8.8 (pyh = map row)
pyh        = 0x24
palo       = 0x25       ; 4 * pa, 10 bits
pahi       = 0x26
mi0        = 0x27       ; player's map cell (row * 16 + column)
col        = 0x28       ; view column 0-79
alo        = 0x29       ; ray angle 0-1023
ahi        = 0x2A
ddxl       = 0x2B       ; |1 / cos|, 8.8
ddxh       = 0x2C
ddyl       = 0x2D       ; |1 / sin|
ddyh       = 0x2E
sxl        = 0x2F       ; distance to the next x crossing
sxh        = 0x30
syl        = 0x31       ; distance to the next y crossing
syh        = 0x32
mi         = 0x33       ; map cell the ray is in
wv         = 0x34       ; map value of the wall hit, + x10 on a y side
dsl        = 0x35       ; distance along the ray to the wall
dsh        = 0x36
hr         = 0x37       ; half height before the fish-eye correction
hh         = 0x38       ; half height 0-56
tmp        = 0x39
mA         = 0x3A       ; multiply: mRH:mRL = mA * mB
mB         = 0x3B
mDL        = 0x3C
mDH        = 0x3D
mRL        = 0x3E
mRH        = 0x3F
colpage    = 0x40       ; video page of this column (x61 + 2 * col)
wcol       = 0x41       ; wall color (never 0)
e_ceil     = 0x42       ; store run entry points (low bytes)
e_floor    = 0x43
e_wall     = 0x44
w_pg       = 0x45       ;   wall run page of e_wall
w_stub     = 0x46       ;   and the low byte of that page's stub
last_frame = 0x47       ; FRAME_LO when the last view started
nticks     = 0x48       ; frames since then (ticks to move)
inp        = 0x49       ; input bits: 0 fwd, 1 back, 2 left, 3 right
demo       = 0x4A       ; 1 while the demo walk runs
sc_i       = 0x4B       ; demo walk step (byte offset into SCRIPT)
sc_n       = 0x4C       ;   ticks left in it
idle_lo    = 0x4D       ; ticks with no input
idle_hi    = 0x4E
tbits      = 0x4F       ; this tick's input
mvd        = 0x50       ; move: dx or dy
nlo        = 0x51       ;   new coordinate
nhi        = 0x52
prb        = 0x53       ;   probe cell
mvp        = 0x54       ;   move angle
views_lo   = 0x55       ; views drawn
views_hi   = 0x56
vticks     = 0x57       ; frames from the last view to this one
fxq        = 0x60       ; x60-x63: f for x by quadrant (255 - frac or frac)
fyq        = 0x64       ; x64-x67: f for y by quadrant

DDXL       = 0x8000
DDXH       = 0x8400
DDYL       = 0x8800
DDYH       = 0x8C00
HT         = 0x9000
QL0        = 0xA800
QL1        = 0xA900
QH0        = 0xAA00
QH1        = 0xAB00
MAP        = 0xAC00
COLTAB     = 0xAD00
PAR        = 0xAE00
COLT       = 0xAF00
E_CE       = 0xB000
E_FE       = 0xB100
E_WE       = 0xB200
E_WP       = 0xB300
E_WS       = 0xB400
MVX        = 0xB500
MVY        = 0xB600
MISC       = 0xB700
RADIUS     = 64

; main: set up the screen and the player
#addr 0x6000
main:
    ld   STACK_TOP, ac          ; stack first
    ld   ac, [SP]
    ld   LINK_LO, x             ; CALL port_init
    ld   m_1, [x]
    ld   LINK_HI, x
    ld   m_1 >> 8, [x]
    ld   port_init >> 8, y
    jmp  port_init
m_1:
    ld   LINK_LO, x             ; CALL con_clear (every row 1 bpp 1x, cursor 0, 0)
    ld   m_2, [x]
    ld   LINK_HI, x
    ld   m_2 >> 8, [x]
    ld   con_clear >> 8, y
    jmp  con_clear
m_2:
    ld   0x5A, y                ; rows 32-479 (x5A40-x5BFF): 8 bpp 4x
    ld   0x40, ac
m_mb1:
    ld   ac, x
    ld   MODE_VIEW, [y,x]
    inc
    bne  m_mb1
    ld   0x5B, y
    clr  ac
m_mb2:
    ld   ac, x
    ld   MODE_VIEW, [y,x]
    inc
    bne  m_mb2
MODE_VIEW  = 0x0B
    clr  ac
    ld   ac, [CUR_COL]
    ld   0, ac
    ld   ac, [CUR_ROW]
    ld   s_title, ac
    ld   ac, [R0]
    ld   s_title >> 8, ac
    ld   ac, [R1]
    ld   LINK_LO, x             ; CALL con_puts
    ld   m_s0, [x]
    ld   LINK_HI, x
    ld   m_s0 >> 8, [x]
    ld   con_puts >> 8, y
    jmp  con_puts
m_s0:
    clr  ac
    ld   ac, [CUR_COL]
    ld   1, ac
    ld   ac, [CUR_ROW]
    ld   s_rate, ac
    ld   ac, [R0]
    ld   s_rate >> 8, ac
    ld   ac, [R1]
    ld   LINK_LO, x             ; CALL con_puts
    ld   m_s1, [x]
    ld   LINK_HI, x
    ld   m_s1 >> 8, [x]
    ld   con_puts >> 8, y
    jmp  con_puts
m_s1:
    clr  ac
    ld   ac, [CUR_COL]
    ld   2, ac
    ld   ac, [CUR_ROW]
    ld   s_keys, ac
    ld   ac, [R0]
    ld   s_keys >> 8, ac
    ld   ac, [R1]
    ld   LINK_LO, x             ; CALL con_puts
    ld   m_s2, [x]
    ld   LINK_HI, x
    ld   m_s2 >> 8, [x]
    ld   con_puts >> 8, y
    jmp  con_puts
m_s2:
    ld   0, ac                 ; the player
    ld   ac, [pa]
    ld   128, ac
    ld   ac, [pxl]
    ld   7, ac
    ld   ac, [pxh]
    ld   128, ac
    ld   ac, [pyl]
    ld   7, ac
    ld   ac, [pyh]
    ld   1, ac                  ; demo walk on, from its first step
    ld   ac, [demo]
    clr  ac
    ld   ac, [sc_i]
    ld   ac, [idle_lo]
    ld   ac, [idle_hi]
    ld   ac, [views_lo]
    ld   ac, [views_hi]
    ld   40, ac
    ld   ac, [sc_n]
    ld   LINK_LO, x             ; CALL frame_poll
    ld   m_fp, [x]
    ld   LINK_HI, x
    ld   m_fp >> 8, [x]
    ld   frame_poll >> 8, y
    jmp  frame_poll
m_fp:
    ld   [FRAME_LO], ac
    sub  1, ac                  ; the first view moves one tick
    ld   ac, [last_frame]
    ld   view_loop >> 8, y
    jmp  view_loop

; view_loop: input, movement, then the 80 columns
#addr 0x6200
view_loop:
    ld   LINK_LO, x             ; CALL frame_poll
    ld   v_fp, [x]
    ld   LINK_HI, x
    ld   v_fp >> 8, [x]
    ld   frame_poll >> 8, y
    jmp  frame_poll
v_fp:
    ld   [FRAME_LO], ac         ; ticks = frames since the last view
    sub  [last_frame], ac
    beq  view_loop              ; (never: a view takes longer than a frame)
    ld   ac, [nticks]
    ld   ac, [vticks]
    ld   [FRAME_LO], ac
    ld   ac, [last_frame]
    ld   LINK_LO, x             ; CALL pad_read
    ld   v_pad, [x]
    ld   LINK_HI, x
    ld   v_pad >> 8, [x]
    ld   pad_read >> 8, y
    jmp  pad_read
v_pad:
    ld   LINK_LO, x             ; CALL kbd_scan
    ld   v_kbd, [x]
    ld   LINK_HI, x
    ld   v_kbd >> 8, [x]
    ld   kbd_scan >> 8, y
    jmp  kbd_scan
v_kbd:
    clr  ac
    ld   ac, [inp]
    ld   [R0], ac               ; pad: up
    and  0x10, ac
    beq  v_i1
    ld   1, ac
    ld   ac, [inp]
v_i1:
    ld   [R0], ac               ; down
    and  0x20, ac
    beq  v_i2
    ld   [inp], ac
    or   2, ac
    ld   ac, [inp]
v_i2:
    ld   [R0], ac               ; left
    and  0x40, ac
    beq  v_i3
    ld   [inp], ac
    or   4, ac
    ld   ac, [inp]
v_i3:
    ld   [R0], ac               ; right
    and  0x80, ac
    beq  v_i4
    ld   [inp], ac
    or   8, ac
    ld   ac, [inp]
v_i4:
    ld   [KBD_NOW + 6], ac      ; Up key
    and  0x20, ac
    bne  v_k1
    ld   [inp], ac
    or   1, ac
    ld   ac, [inp]
v_k1:
    ld   [KBD_NOW + 7], ac      ; Left
    and  0x20, ac
    bne  v_k2
    ld   [inp], ac
    or   4, ac
    ld   ac, [inp]
v_k2:
    ld   [KBD_NOW + 7], ac      ; Down
    and  0x40, ac
    bne  v_k3
    ld   [inp], ac
    or   2, ac
    ld   ac, [inp]
v_k3:
    ld   [KBD_NOW + 7], ac      ; Right
    and  0x80, ac
    bne  v_k4
    ld   [inp], ac
    or   8, ac
    ld   ac, [inp]
v_k4:
    ld   [inp], ac              ; any input: the player drives, idle = 0
    beq  v_idle
    clr  ac
    ld   ac, [demo]
    ld   ac, [idle_lo]
    ld   ac, [idle_hi]
    bra  v_mode
v_idle:
    ld   [demo], ac             ; no input: count idle ticks, demo walk
    bne  v_mode                 ;   again after IDLE_TICKS
    ld   [idle_lo], ac
    add  [nticks], ac
    ld   ac, [idle_lo]
    ld   [idle_hi], ac
    bcc  v_id1
    add  1, ac
    ld   ac, [idle_hi]
v_id1:
    sub  IDLE_TICKS >> 8, ac
    bcs  v_mode
    bne  v_id2
    ld   [idle_lo], ac
    sub  IDLE_TICKS & 0xFF, ac
    bcs  v_mode
v_id2:
    ld   1, ac
    ld   ac, [demo]
v_mode:
IDLE_TICKS = 600
    ld   ticks >> 8, y
    jmp  ticks

; ticks: move the player once per frame since the last view
#addr 0x6400
ticks:
    ld   [inp], ac              ; this tick's input: the player's, or the
    ld   ac, [tbits]            ; demo walk's next step
    ld   [demo], ac
    beq  t_turn
    ld   [sc_i], ac
    add  (SCRIPT & 0xFF) + 1, ac
    ld   ac, x
    ld   SCRIPT >> 8, y
    ld   [y,x], ac
    ld   ac, [tbits]
    ld   [sc_n], ac
    sub  1, ac
    ld   ac, [sc_n]
    bne  t_turn
    ld   [sc_i], ac             ; next step (2 bytes each, 00 ends the list)
    add  2, ac
    ld   ac, [sc_i]
    add  SCRIPT & 0xFF, ac
    ld   ac, x
    ld   [y,x], ac
    bne  t_sc1
    clr  ac
    ld   ac, [sc_i]
    ld   SCRIPT & 0xFF, x
    ld   [y,x], ac
t_sc1:
    ld   ac, [sc_n]
t_turn:
    ld   [tbits], ac            ; turn
    and  4, ac
    beq  t_t1
    ld   [pa], ac
    sub  TURN, ac
    ld   ac, [pa]
t_t1:
    ld   [tbits], ac
    and  8, ac
    beq  t_t2
    ld   [pa], ac
    add  TURN, ac
    ld   ac, [pa]
t_t2:
    ld   [tbits], ac            ; walk: forward at pa, back at pa + 128
    and  3, ac
    bne  t_walk
    ld   t_next >> 8, y
    jmp  t_next
t_walk:
    and  1, ac
    beq  t_back
    clr  ac
    bra  t_fw
t_back:
    ld   0x80, ac
t_fw:
    xor  [pa], ac
    ld   ac, [mvp]
TURN       = 2
    ld   [mvp], x               ; dx
    ld   MVX >> 8, y
    ld   [y,x], ac
    beq  tx_done
    ld   ac, [mvd]
    blt  tx_neg
    add  [pxl], ac             ; new = pos + d (d > 0)
    ld   ac, [nlo]
    ld   [pxh], ac
    bcc  tx_p1
    add  1, ac
tx_p1:
    ld   ac, [nhi]
    ld   [nlo], ac              ; probe = new + RADIUS
    add  RADIUS, ac
    ld   [nhi], ac
    bcc  tx_p2
    add  1, ac
tx_p2:
    ld   ac, [prb]
    bra  tx_chk
tx_neg:
    add  [pxl], ac             ; new = pos + d (d < 0: the high byte - 1 + carry)
    ld   ac, [nlo]
    ld   [pxh], ac
    bcs  tx_n1
    sub  1, ac
tx_n1:
    ld   ac, [nhi]
    ld   [nlo], ac              ; probe = new - RADIUS
    sub  RADIUS, ac
    ld   [nhi], ac
    bcc  tx_n2
    sub  1, ac
tx_n2:
    ld   ac, [prb]
tx_chk:
    ld   [pyh], ac              ; probe cell = row * 16 + column
    shl
    shl
    shl
    shl
    or   [prb], ac
    ld   ac, x
    ld   MAP >> 8, y
    ld   [y,x], ac
    bne  tx_done               ; a wall: stay
    ld   [nlo], ac
    ld   ac, [pxl]
    ld   [nhi], ac
    ld   ac, [pxh]
tx_done:
    ld   hop_1 >> 8, y
    jmp  hop_1                  ; (to the next page)
#addr 0x6500
hop_1:
    ld   [mvp], x               ; dy
    ld   MVY >> 8, y
    ld   [y,x], ac
    beq  ty_done
    ld   ac, [mvd]
    blt  ty_neg
    add  [pyl], ac             ; new = pos + d (d > 0)
    ld   ac, [nlo]
    ld   [pyh], ac
    bcc  ty_p1
    add  1, ac
ty_p1:
    ld   ac, [nhi]
    ld   [nlo], ac              ; probe = new + RADIUS
    add  RADIUS, ac
    ld   [nhi], ac
    bcc  ty_p2
    add  1, ac
ty_p2:
    ld   ac, [prb]
    bra  ty_chk
ty_neg:
    add  [pyl], ac             ; new = pos + d (d < 0: the high byte - 1 + carry)
    ld   ac, [nlo]
    ld   [pyh], ac
    bcs  ty_n1
    sub  1, ac
ty_n1:
    ld   ac, [nhi]
    ld   [nlo], ac              ; probe = new - RADIUS
    sub  RADIUS, ac
    ld   [nhi], ac
    bcc  ty_n2
    sub  1, ac
ty_n2:
    ld   ac, [prb]
ty_chk:
    ld   [prb], ac              ; probe cell = row * 16 + column
    shl
    shl
    shl
    shl
    or   [pxh], ac
    ld   ac, x
    ld   MAP >> 8, y
    ld   [y,x], ac
    bne  ty_done               ; a wall: stay
    ld   [nlo], ac
    ld   ac, [pyl]
    ld   [nhi], ac
    ld   ac, [pyh]
ty_done:
t_next:
    ld   [nticks], ac
    sub  1, ac
    ld   ac, [nticks]
    beq  t_end
    ld   ticks >> 8, y
    jmp  ticks
t_end:
    ld   [pa], ac               ; palo:pahi = 4 * pa
    shl
    shl
    ld   ac, [palo]
    ld   [pa], ac
    shr  ac
    shr  ac
    shr  ac
    shr  ac
    shr  ac
    shr  ac
    ld   ac, [pahi]
    ld   [pxl], ac              ; f for x: quadrants 0 and 3 step +1
    ld   ac, [fxq + 1]
    ld   ac, [fxq + 2]
    xor  255, ac
    ld   ac, [fxq + 0]
    ld   ac, [fxq + 3]
    ld   [pyl], ac              ; f for y: quadrants 0 and 1 step +16
    ld   ac, [fyq + 2]
    ld   ac, [fyq + 3]
    xor  255, ac
    ld   ac, [fyq + 0]
    ld   ac, [fyq + 1]
    ld   [pyh], ac              ; player's cell
    shl
    shl
    shl
    shl
    or   [pxh], ac
    ld   ac, [mi0]
    clr  ac
    ld   ac, [col]
    ld   col_top >> 8, y
    jmp  col_top

; col_top: one ray (common part: angle, steps, first crossings)
#addr 0x6600
col_top:
    ld   [col], x               ; ray angle = 4 * pa + COLANG[col]
    ld   COLT >> 8, y
    ld   [y,x], ac
    ld   ac, [tmp]
    ld   [col], ac
    add  0x50, ac               ; COLANG high bytes at COLT + x50
    ld   ac, x
    ld   [y,x], ac
    ld   ac, [ahi]
    ld   [tmp], ac
    add  [palo], ac
    ld   ac, [alo]
    ld   [ahi], ac
    bcc  c_a1
    add  1, ac
c_a1:
    add  [pahi], ac
    and  3, ac
    ld   ac, [ahi]
    ld   [alo], x               ; the four |1 / cos|, |1 / sin| bytes
    ld   [ahi], ac
    add  DDXL >> 8, y
    ld   [y,x], ac
    ld   ac, [ddxl]
    ld   [ahi], ac
    add  DDXH >> 8, y
    ld   [y,x], ac
    ld   ac, [ddxh]
    ld   [ahi], ac
    add  DDYL >> 8, y
    ld   [y,x], ac
    ld   ac, [ddyl]
    ld   [ahi], ac
    add  DDYH >> 8, y
    ld   [y,x], ac
    ld   ac, [ddyh]
    ld   [ahi], ac              ; mA = f for x in this quadrant
    add  fxq, x
    ld   [x], ac
    ld   ac, [mA]
    ld   [ddxl], ac
    ld   ac, [mB]
    ld   [mA], ac             ; sideX = hi(f * ddxl) + f * ddxh: mA * mB: d = |a - b|
    sub  [mB], ac
    bcc  mx1_dp
    xor  255, ac
    add  1, ac
mx1_dp:
    ld   ac, x
    ld   QL0 >> 8, y            ; Q(d)
    ld   [y,x], ac
    ld   ac, [mDL]
    ld   QH0 >> 8, y
    ld   [y,x], ac
    ld   ac, [mDH]
    ld   [mA], ac             ; s = a + b, 9 bits (carry)
    add  [mB], ac
    ld   ac, x
    bcs  mx1_big
    ld   QL0 >> 8, y            ; Q(s) - Q(d)
    ld   [y,x], ac
    sub  [mDL], ac
    ld   ac, [mRL]
    ld   QH0 >> 8, y
    ld   [y,x], ac
    bcc  mx1_n0
    sub  1, ac
mx1_n0:
    sub  [mDH], ac
    ld   ac, [mRH]
    bra  mx1_end
mx1_big:
    ld   QL1 >> 8, y
    ld   [y,x], ac
    sub  [mDL], ac
    ld   ac, [mRL]
    ld   QH1 >> 8, y
    ld   [y,x], ac
    bcc  mx1_n1
    sub  1, ac
mx1_n1:
    sub  [mDH], ac
    ld   ac, [mRH]
mx1_end:
    ld   [mRH], ac
    ld   ac, [tmp]
    ld   [ddxh], ac
    ld   ac, [mB]
    ld   [mA], ac             ; mA * mB: d = |a - b|
    sub  [mB], ac
    bcc  mx2_dp
    xor  255, ac
    add  1, ac
mx2_dp:
    ld   ac, x
    ld   QL0 >> 8, y            ; Q(d)
    ld   [y,x], ac
    ld   ac, [mDL]
    ld   QH0 >> 8, y
    ld   [y,x], ac
    ld   ac, [mDH]
    ld   [mA], ac             ; s = a + b, 9 bits (carry)
    add  [mB], ac
    ld   ac, x
    bcs  mx2_big
    ld   QL0 >> 8, y            ; Q(s) - Q(d)
    ld   [y,x], ac
    sub  [mDL], ac
    ld   ac, [mRL]
    ld   QH0 >> 8, y
    ld   [y,x], ac
    bcc  mx2_n0
    sub  1, ac
mx2_n0:
    sub  [mDH], ac
    ld   ac, [mRH]
    bra  mx2_end
mx2_big:
    ld   QL1 >> 8, y
    ld   [y,x], ac
    sub  [mDL], ac
    ld   ac, [mRL]
    ld   QH1 >> 8, y
    ld   [y,x], ac
    bcc  mx2_n1
    sub  1, ac
mx2_n1:
    sub  [mDH], ac
    ld   ac, [mRH]
mx2_end:
    ld   [mRL], ac
    add  [tmp], ac
    ld   ac, [sxl]
    ld   [mRH], ac
    bcc  c_x1
    add  1, ac
c_x1:
    ld   ac, [sxh]
    ld   [ahi], ac              ; mA = f for y
    add  fyq, x
    ld   [x], ac
    ld   ac, [mA]
    ld   [ddyl], ac
    ld   ac, [mB]
    ld   hop_2 >> 8, y
    jmp  hop_2                  ; (to the next page)
#addr 0x6700
hop_2:
    ld   [mA], ac             ; sideY: mA * mB: d = |a - b|
    sub  [mB], ac
    bcc  my1_dp
    xor  255, ac
    add  1, ac
my1_dp:
    ld   ac, x
    ld   QL0 >> 8, y            ; Q(d)
    ld   [y,x], ac
    ld   ac, [mDL]
    ld   QH0 >> 8, y
    ld   [y,x], ac
    ld   ac, [mDH]
    ld   [mA], ac             ; s = a + b, 9 bits (carry)
    add  [mB], ac
    ld   ac, x
    bcs  my1_big
    ld   QL0 >> 8, y            ; Q(s) - Q(d)
    ld   [y,x], ac
    sub  [mDL], ac
    ld   ac, [mRL]
    ld   QH0 >> 8, y
    ld   [y,x], ac
    bcc  my1_n0
    sub  1, ac
my1_n0:
    sub  [mDH], ac
    ld   ac, [mRH]
    bra  my1_end
my1_big:
    ld   QL1 >> 8, y
    ld   [y,x], ac
    sub  [mDL], ac
    ld   ac, [mRL]
    ld   QH1 >> 8, y
    ld   [y,x], ac
    bcc  my1_n1
    sub  1, ac
my1_n1:
    sub  [mDH], ac
    ld   ac, [mRH]
my1_end:
    ld   [mRH], ac
    ld   ac, [tmp]
    ld   [ddyh], ac
    ld   ac, [mB]
    ld   [mA], ac             ; mA * mB: d = |a - b|
    sub  [mB], ac
    bcc  my2_dp
    xor  255, ac
    add  1, ac
my2_dp:
    ld   ac, x
    ld   QL0 >> 8, y            ; Q(d)
    ld   [y,x], ac
    ld   ac, [mDL]
    ld   QH0 >> 8, y
    ld   [y,x], ac
    ld   ac, [mDH]
    ld   [mA], ac             ; s = a + b, 9 bits (carry)
    add  [mB], ac
    ld   ac, x
    bcs  my2_big
    ld   QL0 >> 8, y            ; Q(s) - Q(d)
    ld   [y,x], ac
    sub  [mDL], ac
    ld   ac, [mRL]
    ld   QH0 >> 8, y
    ld   [y,x], ac
    bcc  my2_n0
    sub  1, ac
my2_n0:
    sub  [mDH], ac
    ld   ac, [mRH]
    bra  my2_end
my2_big:
    ld   QL1 >> 8, y
    ld   [y,x], ac
    sub  [mDL], ac
    ld   ac, [mRL]
    ld   QH1 >> 8, y
    ld   [y,x], ac
    bcc  my2_n1
    sub  1, ac
my2_n1:
    sub  [mDH], ac
    ld   ac, [mRH]
my2_end:
    ld   [mRL], ac
    add  [tmp], ac
    ld   ac, [syl]
    ld   [mRH], ac
    bcc  c_y1
    add  1, ac
c_y1:
    ld   ac, [syh]
    ld   [mi0], ac
    ld   ac, [mi]
    ld   [ahi], ac              ; DDA for this quadrant: page DDA0 + quadrant
    add  dda0 >> 8, y
    jmp  dda0

; DDA, quadrant 0: x step +1, y step +16
#addr 0x6C00
dda0:
d0_lp:
    ld   [sxh], ac              ; sideX < sideY ?
    sub  [syh], ac
    bne  d0_ne
    ld   [sxl], ac
    sub  [syl], ac
d0_ne:
    bcs  d0_x
    ld   [syl], ac              ; step y: sideY += ddy
    add  [ddyl], ac
    ld   ac, [syl]
    ld   [syh], ac
    bcc  d0_y1
    add  1, ac
d0_y1:
    add  [ddyh], ac
    ld   ac, [syh]
    ld   [mi], ac
    add  16, ac
    ld   ac, [mi]
    ld   ac, x
    ld   MAP >> 8, y
    ld   [y,x], ac
    beq  d0_lp
    or   0x10, ac               ; a y side
    ld   ac, [wv]
    ld   [syl], ac              ; distance = sideY - ddy
    sub  [ddyl], ac
    ld   ac, [dsl]
    ld   [syh], ac
    bcc  d0_y2
    sub  1, ac
d0_y2:
    sub  [ddyh], ac
    ld   ac, [dsh]
    ld   hit >> 8, y
    jmp  hit
d0_x:
    ld   [sxl], ac              ; step x: sideX += ddx
    add  [ddxl], ac
    ld   ac, [sxl]
    ld   [sxh], ac
    bcc  d0_x1
    add  1, ac
d0_x1:
    add  [ddxh], ac
    ld   ac, [sxh]
    ld   [mi], ac
    add  1, ac
    ld   ac, [mi]
    ld   ac, x
    ld   MAP >> 8, y
    ld   [y,x], ac
    beq  d0_lp
    ld   ac, [wv]
    ld   [sxl], ac              ; distance = sideX - ddx
    sub  [ddxl], ac
    ld   ac, [dsl]
    ld   [sxh], ac
    bcc  d0_x2
    sub  1, ac
d0_x2:
    sub  [ddxh], ac
    ld   ac, [dsh]
    ld   hit >> 8, y
    jmp  hit

; DDA, quadrant 1: x step -1, y step +16
#addr 0x6D00
d1_lp:
    ld   [sxh], ac              ; sideX < sideY ?
    sub  [syh], ac
    bne  d1_ne
    ld   [sxl], ac
    sub  [syl], ac
d1_ne:
    bcs  d1_x
    ld   [syl], ac              ; step y: sideY += ddy
    add  [ddyl], ac
    ld   ac, [syl]
    ld   [syh], ac
    bcc  d1_y1
    add  1, ac
d1_y1:
    add  [ddyh], ac
    ld   ac, [syh]
    ld   [mi], ac
