d1_x1:
    add  [ddxh], ac
    ld   ac, [sxh]
    ld   [mi], ac
    add  255, ac
    ld   ac, [mi]
    ld   ac, x
    ld   MAP >> 8, y
    ld   [y,x], ac
    beq  d1_lp
    ld   ac, [wv]
    ld   [sxl], ac              ; distance = sideX - ddx
    sub  [ddxl], ac
