d2_y1:
    add  [ddyh], ac
    ld   ac, [syh]
    ld   [mi], ac
    add  240, ac
    ld   ac, [mi]
    ld   ac, x
    ld   MAP >> 8, y
    ld   [y,x], ac
    beq  d2_lp
    or   0x10, ac               ; a y side
    ld   ac, [wv]
    ld   [syl], ac              ; distance = sideY - ddy
    sub  [ddyl], ac
