d2_x:
    ld   [sxl], ac              ; step x: sideX += ddx
    add  [ddxl], ac
    ld   ac, [sxl]
    ld   [sxh], ac
    bcc  d2_x1
    add  1, ac
d2_x1:
    add  [ddxh], ac
    ld   ac, [sxh]
    ld   [mi], ac
    add  255, ac
    ld   ac, [mi]
    ld   ac, x
    ld   MAP >> 8, y
    ld   [y,x], ac
    beq  d2_lp
