; DDA, quadrant 3: x step +1, y step -16
#addr 0x6F00
d3_lp:
    ld   [sxh], ac              ; sideX < sideY ?
    sub  [syh], ac
    bne  d3_ne
    ld   [sxl], ac
    sub  [syl], ac
d3_ne:
    bcs  d3_x
    ld   [syl], ac              ; step y: sideY += ddy
    add  [ddyl], ac
    ld   ac, [syl]
    ld   [syh], ac
    bcc  d3_y1
    add  1, ac
d3_y1:
    add  [ddyh], ac
    ld   ac, [syh]
    ld   [mi], ac
    add  240, ac
