    ld   ac, [mi]
    ld   ac, x
    ld   MAP >> 8, y
    ld   [y,x], ac
    beq  d3_lp
    ld   ac, [wv]
    ld   [sxl], ac              ; distance = sideX - ddx
    sub  [ddxl], ac
    ld   ac, [dsl]
    ld   [sxh], ac
