; hit: wall height, color and the store run entry points
#addr 0x7000
hit:
    ld   [dsh], ac              ; hr = HT[distance] (1 when 24 cells or more)
    sub  HT_PAGES, ac
    bcc  h_far
    ld   [dsh], ac
    add  HT >> 8, y
    ld   [dsl], x
    ld   [y,x], ac
    bra  h_got
h_far:
    ld   1, ac
h_got:
    ld   ac, [hr]
    sub  HALF, ac
    bcs  h_mul
    ld   HALF, ac
    ld   ac, [hh]
    ld   h_col >> 8, y
    jmp  h_col
h_mul:
    ld   [hr], ac               ; fish-eye: h = hr + hr * KC[col] / 256
    ld   ac, [mA]
    ld   [col], ac
    add  0xA0, ac
    ld   ac, x
    ld   COLT >> 8, y
    ld   [y,x], ac
    ld   ac, [mB]
HT_PAGES   = 24
HALF       = 56
    ld   [mA], ac             ; mA * mB: d = |a - b|
    sub  [mB], ac
    bcc  mh_dp
    xor  255, ac
    add  1, ac
mh_dp:
    ld   ac, x
    ld   QL0 >> 8, y            ; Q(d)
    ld   [y,x], ac
    ld   ac, [mDL]
    ld   QH0 >> 8, y
    ld   [y,x], ac
    ld   ac, [mDH]
    ld   [mA], ac             ; s = a + b, 9 bits (carry)
    add  [mB], ac
    ld   ac, x
    bcs  mh_big
    ld   QL0 >> 8, y            ; Q(s) - Q(d)
    ld   [y,x], ac
    sub  [mDL], ac
    ld   ac, [mRL]
    ld   QH0 >> 8, y
    ld   [y,x], ac
    bcc  mh_n0
    sub  1, ac
mh_n0:
    sub  [mDH], ac
    ld   ac, [mRH]
    bra  mh_end
mh_big:
    ld   QL1 >> 8, y
    ld   [y,x], ac
    sub  [mDL], ac
    ld   ac, [mRL]
    ld   QH1 >> 8, y
    ld   [y,x], ac
    bcc  mh_n1
    sub  1, ac
mh_n1:
    sub  [mDH], ac
    ld   ac, [mRH]
mh_end:
    ld   [mRH], ac
    add  [hr], ac
    ld   ac, [hh]
    sub  HALF + 1, ac
    bcs  h_col
    ld   HALF, ac
    ld   ac, [hh]
h_col:
    ld   [hh], ac               ; color = COLTAB[wv | PAR[mi] | h / 8]
    shr  ac
    shr  ac
    shr  ac
    ld   ac, [tmp]
    ld   [mi], x
    ld   PAR >> 8, y
    ld   [y,x], ac
    or   [tmp], ac
    or   [wv], ac
    ld   ac, x
    ld   COLTAB >> 8, y
    ld   [y,x], ac
    ld   ac, [wcol]
    ld   [hh], x                ; store run entry points for h
    ld   E_CE >> 8, y
    ld   [y,x], ac
    ld   ac, [e_ceil]
    ld   E_FE >> 8, y
    ld   [y,x], ac
    ld   ac, [e_floor]
    ld   E_WE >> 8, y
    ld   [y,x], ac
    ld   ac, [e_wall]
    ld   E_WP >> 8, y
    ld   [y,x], ac
    ld   ac, [w_pg]
    ld   E_WS >> 8, y
    ld   [y,x], ac
    ld   ac, [w_stub]
    ld   [col], ac              ; video page x61 + 2 * col
    shl
    add  0x61, ac
    ld   ac, [colpage]
    ld   ceil_stub >> 8, y
    jmp  ceil_stub
col_next:
    ld   [col], ac              ; next column
    add  1, ac
    ld   ac, [col]
    sub  NCOL, ac
    bne  c_more
    ld   view_done >> 8, y
    jmp  view_done
c_more:
NCOL       = 80
    ld   LINK_LO, x             ; CALL frame_poll (keeps the frame count during the view)
    ld   c_fp, [x]
    ld   LINK_HI, x
    ld   c_fp >> 8, [x]
    ld   frame_poll >> 8, y
    jmp  frame_poll
c_fp:
    ld   col_top >> 8, y
    jmp  col_top

; view_done: frame rate on the text rows
#addr 0x7200
view_done:
    ld   [views_lo], ac         ; views drawn
    add  1, ac
    ld   ac, [views_lo]
    bcc  vd_1
    ld   [views_hi], ac
    add  1, ac
    ld   ac, [views_hi]
vd_1:
    ld   RATE_COL, ac           ; "nn" views a second, from the frames since
    ld   ac, [CUR_COL]          ; the last view
    ld   1, ac
    ld   ac, [CUR_ROW]
    ld   [vticks], ac
    and  63, ac
    ld   ac, [tmp]
    ld   ac, x
    ld   FPS_T >> 8, y
    ld   [y,x], ac
    ld   LINK_LO, x             ; CALL con_putc
    ld   vd_2, [x]
    ld   LINK_HI, x
    ld   vd_2 >> 8, [x]
    ld   con_putc >> 8, y
    jmp  con_putc
vd_2:
    ld   [tmp], ac
    add  FPS_O & 0xFF, ac
    ld   ac, x
    ld   FPS_O >> 8, y
    ld   [y,x], ac
    ld   LINK_LO, x             ; CALL con_putc
    ld   vd_3, [x]
    ld   LINK_HI, x
    ld   vd_3 >> 8, [x]
    ld   con_putc >> 8, y
    jmp  con_putc
vd_3:
    ld   MODE_COL, ac           ; "DEMO WALK" or "YOU DRIVE"
    ld   ac, [CUR_COL]
    ld   1, ac
    ld   ac, [CUR_ROW]
    ld   s_demo, ac
    ld   ac, [R0]
    ld   [demo], ac
    bne  vd_4
    ld   s_you, ac
    ld   ac, [R0]
vd_4:
    ld   s_demo >> 8, ac
    ld   ac, [R1]
    ld   LINK_LO, x             ; CALL con_puts
    ld   vd_5, [x]
    ld   LINK_HI, x
    ld   vd_5 >> 8, [x]
    ld   con_puts >> 8, y
    jmp  con_puts
vd_5:
    ld   view_loop >> 8, y
    jmp  view_loop

